python3 -c "
import json

with open('artifacts/clause_templates.json') as f:
    data = json.load(f)

# Look at a few 2-response clauses from each type to understand patterns
for atype in ['scopal', 'lexical', 'incompleteness']:
    count = 0
    for c in data:
        if c['ambiguity_type'] != atype:
            continue
        tr = c.get('tool_responses', [])
        if len(tr) == 2:
            if count >= 2:
                continue
            count += 1
            print(f'=== {c[\"clause_id\"]} ({atype}) — 2 responses ===')
            print('tools:', [t['function']['name'] for t in c.get('tools', [])])
            print('domain:', c.get('domain', ''))
            print('user_scenario:', c.get('user_scenario', '')[:200])
            for i, r in enumerate(tr):
                print(f'  resp[{i}]: tool={r[\"tool_name\"]}, args={r[\"args_pattern\"]}')
                # Just print response keys and a summary
                resp = r['response']
                if isinstance(resp, dict):
                    print(f'    response keys: {list(resp.keys())}')
                else:
                    print(f'    response: {str(resp)[:200]}')
            print()

# Also look at 3+ response ones for lexical/incompleteness
print('\\n=== EXAMPLES WITH 3+ RESPONSES ===')
for atype in ['lexical', 'incompleteness']:
    for c in data:
        if c['ambiguity_type'] != atype:
            continue
        tr = c.get('tool_responses', [])
        if len(tr) >= 3:
            print(f'{c[\"clause_id\"]} ({atype}): {len(tr)} responses')
            print('tools:', [t['function']['name'] for t in c.get('tools', [])])
            for i, r in enumerate(tr):
                print(f'  resp[{i}]: tool={r[\"tool_name\"]}, args_keys={list(r[\"args_pattern\"].keys())}')
            print()
            break
" 2>&1

