def process_file(filepath, filter_type=None):
    """Process a single JSON file, supplementing tool_responses."""
    with open(filepath) as f:
        data = json.load(f)

    changelog = []

    for clause in data:
        cid = clause["clause_id"]
        atype = clause.get("ambiguity_type", "")

        if filter_type and atype != filter_type:
            continue

        tr = clause.get("tool_responses", [])
        original_count = len(tr)

        if original_count >= 3:
            continue

        if cid not in SUPPLEMENTS:
            print(f"WARNING: No supplement defined for {cid}")
            continue

        new_responses = SUPPLEMENTS[cid]
        needed = 3 - original_count
        to_add = new_responses[:needed]

        clause["tool_responses"].extend(to_add)

        added_descs = [f"{r['tool_name']}: {list(r['args_pattern'].keys())}" for r in to_add]
        changelog.append({
            "clause_id": cid,
            "source_file": filepath.name,
            "original_count": original_count,
            "new_count": len(clause["tool_responses"]),
            "added_responses": added_descs
        })

    with open(filepath, "w") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)

    return changelog


def collect_stats(filepath, filter_type=None):
    """Collect per-type stats for tool_responses counts."""
    with open(filepath) as f:
        data = json.load(f)

    stats = {}
    for clause in data:
        atype = clause.get("ambiguity_type", "unknown")
        if filter_type and atype != filter_type:
            continue
        tr = clause.get("tool_responses", [])
        count = len(tr)
        if atype not in stats:
            stats[atype] = []
        stats[atype].append(count)

    return stats


def print_stats(label, stats):
    print(f"\n{'='*50}")
    print(f"  {label}")
    print(f"{'='*50}")
    for atype in sorted(stats.keys()):
        counts = stats[atype]
        avg = sum(counts) / len(counts)
        mn = min(counts)
        mx = max(counts)
        below3 = sum(1 for c in counts if c < 3)
        print(f"  {atype:25s}  n={len(counts):3d}  avg={avg:.1f}  min={mn}  max={mx}  below3={below3}")


def main():
    files = [
        (ARTIFACTS / "clause_templates.json", None),
        (ARTIFACTS / "clauses_supplement.json", None),
        (ARTIFACTS / "clause_templates_diag001.json", "scopal"),
    ]

    # Collect BEFORE stats
    print("BEFORE SUPPLEMENTATION:")
    before_stats = {}
    for filepath, filter_type in files:
        stats = collect_stats(filepath, filter_type)
        print_stats(filepath.name, stats)
        for k, v in stats.items():
            key = f"{filepath.name}:{k}"
            before_stats[key] = v

    # Process files
    all_changelog = []
    for filepath, filter_type in files:
        changelog = process_file(filepath, filter_type)
        all_changelog.extend(changelog)
        print(f"\nProcessed {filepath.name}: {len(changelog)} clauses supplemented")

    # Collect AFTER stats
    print("\n\nAFTER SUPPLEMENTATION:")
    after_stats = {}
    for filepath, filter_type in files:
        stats = collect_stats(filepath, filter_type)
        print_stats(filepath.name, stats)
        for k, v in stats.items():
            key = f"{filepath.name}:{k}"
            after_stats[key] = v

    # Write changelog
    with open(ARTIFACTS / "tool_response_supplement_log.json", "w") as f:
        json.dump(all_changelog, f, indent=2, ensure_ascii=False)
    print(f"\nChangelog written: {len(all_changelog)} entries -> artifacts/tool_response_supplement_log.json")

    # Verification
    print("\n\nVERIFICATION:")
    failures = 0
    for filepath, filter_type in files:
        with open(filepath) as f:
            data = json.load(f)
        for clause in data:
            if filter_type and clause.get("ambiguity_type") != filter_type:
                continue
            tr = clause.get("tool_responses", {})
            count = len(tr) if isinstance(tr, (dict, list)) else 0
            if count < 3:
                print(f"  FAIL: {clause['clause_id']} has {count} tool_responses")
                failures += 1
        print(f"  {filepath.name}: checked")

    if failures == 0:
        print("\n  ALL PASS: Every clause has >= 3 tool_responses")
    else:
        print(f"\n  {failures} FAILURES found")


if __name__ == "__main__":
    main()

